/**
 * Every message the software can show for an error or refusal, with its English text, cause and resolution.
 * The interface uses it to show errors in the selected language; scripts/generate-error-reference.cjs
 * turns it into docs/CN/错误与提示参考.md and docs/English/Error-reference.md, and tests/error-catalog.cjs
 * fails when the code raises a Chinese message that is missing here.
 * Placeholders {1}, {2} stand for values filled in at run time, in order of appearance.
 */
export type ErrorArea='desktop'|'ai'|'account'|'business'|'settings'|'finance'|'retention'|'voice'|'cli'|'server'|'api';
/** [Chinese, English, area, cause (zh), cause (en), resolution (zh) or @token, resolution (en, omitted for tokens)] */
export type ErrorEntry=readonly [zh:string,en:string,area:ErrorArea,causeZh:string,causeEn:string,fixZh:string,fixEn?:string];

export const FIXES:Record<string,readonly [zh:string,en:string]>={
 '@retry':['稍后重试；如果反复出现，请记下发生时间和操作步骤后反馈。','Retry later. If it keeps happening, note the time and the steps taken and report it.'],
 '@login':['重新登录后再试。','Sign in again and retry.'],
 '@refresh':['刷新页面读取最新数据，核对后再操作。','Refresh to load the latest data, check it, then try again.'],
 '@owner':['请超级管理员执行此操作，或请其为你分配相应权限。','Ask the super administrator to perform this operation or to grant you the required permission.'],
 '@report':['这是软件内部的安全检查，正常使用不会出现。请重启软件；仍然出现时，请附上运行日志反馈。','This is an internal safety check that normal use does not trigger. Restart the app; if it persists, report it with the logs.'],
 '@deploy':['由部署负责人按部署手册检查服务器配置，修改后重启服务。','The person who deployed the server should check the configuration against the Deployment manual and restart the service.'],
 '@input':['按提示修改填写内容后重新提交。','Correct the entry as described and submit again.'],
 '@ai':['在“工作室偏好 › AI 服务接入”核对服务商、API 地址、协议与模型后重试。','Check the provider, API address, protocol and model under Preferences › AI service connection, then retry.'],
 '@speech':['在软件内重新安装语音组件，确认网络畅通、磁盘空间充足。','Reinstall the voice components in the app with a working network and enough free disk space.'],
 '@cli':['输入“帮助”或“帮助 模块名”查看固定语法。','Enter Help, or Help followed by a module name, to see the fixed syntax.'],
 '@api':['按接口手册修正请求后重新发送。','Correct the request according to the API reference and send it again.'],
};

